package kr.mujoong.core.result;
import static org.assertj.core.api.Assertions.*;
import java.util.*;
import kr.mujoong.core.web.support.WebFixtures;
import org.junit.jupiter.api.*;
@Tag("u6") @Tag("db")
class ResultApiIT extends U6WebTestSupport {
    @Test void statusWithoutHeadUsesEndedCopy(){var f=family();UUID session=copy(f,"ENDED",null);var user=WebFixtures.guardianFor(app,f.guardianId());var response=checked("GET /api/sessions/{sessionId}/result/status",app.get("/api/sessions/"+session+"/result/status").session(user.session()));assertThat(response.status()).isEqualTo(200);assertThat(response.json()).containsEntry("jobStatus","REQUESTED");}
    @Test void localFailedWithoutRecordHasNone(){var f=family();UUID session=copy(f,"FAILED","INTERNAL");var user=WebFixtures.guardianFor(app,f.guardianId());assertThat(app.get("/api/sessions/"+session+"/result/status").session(user.session()).send().json()).containsEntry("jobStatus","NONE");}
    @Test void declinedRecordHasNone(){var f=family();UUID session=copy(f,"DECLINED",null);record(f,session,"DECLINED",0);var user=WebFixtures.guardianFor(app,f.guardianId());assertThat(app.get("/api/sessions/"+session+"/result/status").session(user.session()).send().json()).containsEntry("jobStatus","NONE");}
    @Test void otherGuardianGetsNotFound(){var f=family();UUID session=copy(f,"ENDED",null);var other=WebFixtures.guardianFor(app,family().guardianId());assertThat(app.get("/api/sessions/"+session+"/result").session(other.session()).send().status()).isEqualTo(404);}
    @Test void deletingGuardianGetsForbidden(){var f=family();UUID session=copy(f,"ENDED",null);var user=WebFixtures.guardianFor(app,f.guardianId());db.jdbc().update("update core.core_guardian set status='DELETION_REQUESTED' where id=:id",Map.of("id",f.guardianId()));assertThat(app.get("/api/sessions/"+session+"/result").session(user.session()).send().status()).isEqualTo(403);}
    @Test void resultResponseContainsOnlyPublicFields(){var f=family();UUID session=copy(f,"ENDED",null);record(f,session,"ENDED",0);var user=WebFixtures.guardianFor(app,f.guardianId());var response=checked("GET /api/sessions/{sessionId}/result",app.get("/api/sessions/"+session+"/result").session(user.session()));assertThat(response.status()).isEqualTo(200);assertThat(response.body()).doesNotContain("rationale","timing","matchingLog","pendingCandidates","knownContent");}
    @Test void retryHas202Then409(){var f=family();UUID session=copy(f,"ENDED",null);var states=app.bean(SessionResultStateRepository.class);states.insert(session,f.guardianId(),f.childId(),"FREE_TALK",true,app.clock().now());db.jdbc().update("update core.core_session_result_state set job_status='FAILED' where session_id=:id",Map.of("id",session));var user=WebFixtures.guardianFor(app,f.guardianId());String path="/api/sessions/"+session+"/result/retry";assertThat(checked("POST /api/sessions/{sessionId}/result/retry",app.post(path).session(user.session()).csrf(user.csrf()).json("{}")).status()).isEqualTo(202);assertThat(app.post(path).session(user.session()).csrf(user.csrf()).json("{}").send().status()).isEqualTo(409);}
    @Test void retryRequiresCsrf(){var f=family();UUID session=copy(f,"ENDED",null);var user=WebFixtures.guardianFor(app,f.guardianId());assertThat(app.post("/api/sessions/"+session+"/result/retry").session(user.session()).json("{}").send().status()).isEqualTo(403);}
}
